404	-- ---------------------------------------------------------------------------------------------
405	-- create_gateway_bill (R30, D5): bill for what is due on or before today's Malaysia date.
406	-- ---------------------------------------------------------------------------------------------
407	create or replace function private.create_gateway_bill(
408	  p_actor_id uuid,
409	  p_lease_id uuid,
410	  p_as_of timestamptz default now()
411	)
412	returns table(id uuid, amount_sen bigint)
413	language plpgsql
414	security invoker
415	set search_path = ''
416	as $$
417	#variable_conflict use_column
418	declare
419	  v_lease record;
420	  v_today date;
421	  v_due bigint;
422	  v_id uuid;
423	begin
424	  -- D7: lease lock so the due amount is computed against committed allocations.
425	  select l.id, l.org_id, l.tenant_id
426	    into v_lease
427	    from public.leases l
428	   where l.id = p_lease_id
429	     for update;
430	  if not found then
431	    raise exception using errcode = 'P0404', message = 'Lease not found';
432	  end if;
433	
434	  -- R1/R37: only the lease's own tenant (tenants.user_id), never another tenant or org.
435	  if not exists (select 1 from public.tenants t
436	                  where t.id = v_lease.tenant_id
437	                    and t.org_id = v_lease.org_id
438	                    and t.user_id = p_actor_id) then
439	    raise exception using errcode = 'P0404', message = 'Lease not found';
440	  end if;
441	
442	  -- D5: "today" is the Malaysia calendar date of p_as_of, never the server's zone.
443	  v_today := (p_as_of at time zone 'Asia/Kuala_Lumpur')::date;
444	
445	  -- R30/D13: unpaid amounts of invoices due on or before today; pending manual payments ignored.
446	  select coalesce(sum(greatest(i.amount_sen - coalesce((select sum(a.amount_sen)
447	                                                          from public.payment_allocations a
448	                                                         where a.invoice_id = i.id), 0), 0)), 0)
449	    into v_due
450	    from public.invoices i
451	   where i.lease_id = p_lease_id
452	     and i.due_date <= v_today;
453	
454	  if v_due <= 0 then
455	    raise exception using errcode = 'P0422', message = 'Nothing is due';
456	  end if;
457	
458	  -- R30: bill id = gen_random_uuid() column default (122 random bits, not guessable).
459	  insert into public.gateway_bills as b (org_id, lease_id, amount_sen, status, created_by)
460	  values (v_lease.org_id, p_lease_id, v_due, 'pending', p_actor_id)
461	  returning b.id into v_id;
462	
463	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
464	  values (v_lease.org_id, p_actor_id, 'gateway_bill.created', v_id,
465	          jsonb_build_object('lease_id', p_lease_id, 'amount_sen', v_due, 'as_of_date', v_today));
466	
467	  return query select v_id, v_due;
468	end;
469	$$;
470	
471	-- ---------------------------------------------------------------------------------------------
472	-- apply_gateway_callback (R34, R35, D10, D11): the bill state machine.
473	-- ---------------------------------------------------------------------------------------------
474	create or replace function private.apply_gateway_callback(
475	  p_bill_id uuid,
476	  p_paid boolean,
477	  p_paid_amount_sen bigint,
478	  p_paid_at timestamptz,
479	  p_transaction_id text,
480	  p_transaction_status text
481	)
482	returns table(outcome text, payment_id uuid)
483	language plpgsql
484	security invoker
485	set search_path = ''
486	as $$
487	#variable_conflict use_column
488	declare
489	  v_bill record;
490	  v_payment_id uuid;
491	begin
492	  -- D7/D10: bill lock first; simultaneous deliveries of one callback queue here, and the second
493	  -- one sees status = 'paid' and returns 'duplicate' (R35: at most one payment per bill).
494	  select b.id, b.org_id, b.lease_id, b.amount_sen, b.status
495	    into v_bill
496	    from public.gateway_bills b
497	   where b.id = p_bill_id
498	     for update;
499	  if not found then
500	    raise exception using errcode = 'P0404', message = 'Unknown bill';
501	  end if;
502	
503	  if p_paid is null then
504	    raise exception using errcode = 'P0400', message = 'paid is required';
505	  end if;
506	
507	  -- D11/R34: amount is compared with the bill's stored amount, whatever the bill's state.
508	  if p_paid and p_paid_amount_sen is distinct from v_bill.amount_sen then
509	    raise exception using errcode = 'P0422', message = 'Paid amount does not match the bill';
510	  end if;
511	
512	  if p_paid then
513	    if v_bill.status = 'paid' then
514	      select p.id into v_payment_id from public.payments p where p.gateway_bill_id = p_bill_id;
515	      return query select 'duplicate'::text, v_payment_id;
516	      return;
517	    end if;
518	    if p_paid_at is null then
519	      raise exception using errcode = 'P0400', message = 'paid_at is required';
520	    end if;
521	
522	    -- D7: bill -> lease, the only path that takes a bill lock, so the order is never inverted.
523	    perform 1 from public.leases l where l.id = v_bill.lease_id for update;
524	
525	    update public.gateway_bills b
526	       set status = 'paid', paid_at = p_paid_at, transaction_id = p_transaction_id,
527	           transaction_status = p_transaction_status, updated_at = now()
528	     where b.id = p_bill_id;
529	
530	    -- R35: UNIQUE (gateway_bill_id) backs up the lock; on conflict we return the existing one.
531	    insert into public.payments as p
532	           (org_id, lease_id, amount_sen, method, status, received_at, gateway_bill_id, decided_at)
533	    values (v_bill.org_id, v_bill.lease_id, v_bill.amount_sen, 'online', 'approved', p_paid_at,
534	            p_bill_id, now())
535	    on conflict do nothing
536	    returning p.id into v_payment_id;
537	
538	    if v_payment_id is null then
539	      select p.id into v_payment_id from public.payments p where p.gateway_bill_id = p_bill_id;
540	      return query select 'duplicate'::text, v_payment_id;
541	      return;
542	    end if;
543	
544	    -- R26: allocate like any approval; what the invoices cannot absorb becomes unapplied_sen
545	    -- (captured money is never refused).
546	    perform private.allocate_payment(v_payment_id);
547	
548	    insert into public.audit_log (org_id, actor_id, action, entity_id, details)
549	    values (v_bill.org_id, null, 'gateway_bill.paid', p_bill_id,
550	            jsonb_build_object('lease_id', v_bill.lease_id, 'payment_id', v_payment_id,
551	                               'amount_sen', v_bill.amount_sen, 'transaction_id', p_transaction_id,
552	                               'transaction_status', p_transaction_status, 'paid_at', p_paid_at));
553	
554	    return query select 'paid'::text, v_payment_id;
555	    return;
556	  end if;
557	
558	  -- paid = false: only a pending bill moves (to failed); failed stays failed, paid never goes back.
559	  if v_bill.status = 'pending' then
560	    update public.gateway_bills b
561	       set status = 'failed', transaction_id = p_transaction_id,
562	           transaction_status = p_transaction_status, updated_at = now()
563	     where b.id = p_bill_id;
564	
565	    insert into public.audit_log (org_id, actor_id, action, entity_id, details)
566	    values (v_bill.org_id, null, 'gateway_bill.failed', p_bill_id,
567	            jsonb_build_object('lease_id', v_bill.lease_id, 'transaction_id', p_transaction_id,
568	                               'transaction_status', p_transaction_status));
569	
570	    return query select 'failed'::text, null::uuid;
571	    return;
572	  end if;
573	
574	  return query select 'ignored'::text, null::uuid;
575	end;
576	$$;
577	
578	-- D8: owner-only. Not callable by anon/authenticated even if the private schema were exposed.
579	revoke execute on function private.allocate_payment(uuid) from public, anon, authenticated;
580	revoke execute on function private.record_payment(uuid, uuid, bigint, text, timestamptz, text, uuid) from public, anon, authenticated;
581	revoke execute on function private.lock_payment_for_manager(uuid, uuid) from public, anon, authenticated;
582	revoke execute on function private.approve_payment(uuid, uuid) from public, anon, authenticated;
583	revoke execute on function private.reject_payment(uuid, uuid, text) from public, anon, authenticated;
584	revoke execute on function private.void_payment(uuid, uuid, text) from public, anon, authenticated;
585	revoke execute on function private.create_gateway_bill(uuid, uuid, timestamptz) from public, anon, authenticated;
586	revoke execute on function private.apply_gateway_callback(uuid, boolean, bigint, timestamptz, text, text) from public, anon, authenticated;
