325	-- ---------------------------------------------------------------------------------------------
326	-- reject_payment (R24)
327	-- ---------------------------------------------------------------------------------------------
328	create or replace function private.reject_payment(p_actor_id uuid, p_payment_id uuid, p_reason text)
329	returns table(status text)
330	language plpgsql
331	security invoker
332	set search_path = ''
333	as $$
334	#variable_conflict use_column
335	declare
336	  v_pay public.payments;
337	begin
338	  -- Error contract order: not found (404) before validation (400) before state (409).
339	  v_pay := private.lock_payment_for_manager(p_actor_id, p_payment_id);
340	
341	  if p_reason is null or length(btrim(p_reason)) < 5 then
342	    raise exception using errcode = 'P0400', message = 'Reason must be at least 5 characters';
343	  end if;
344	  if v_pay.status <> 'pending_verification' then
345	    raise exception using errcode = 'P0409', message = 'Payment is not pending';
346	  end if;
347	
348	  update public.payments p
349	     set status = 'rejected', reason = btrim(p_reason), decided_by = p_actor_id, decided_at = now()
350	   where p.id = p_payment_id;
351	
352	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
353	  values (v_pay.org_id, p_actor_id, 'payment.rejected', p_payment_id,
354	          jsonb_build_object('lease_id', v_pay.lease_id, 'amount_sen', v_pay.amount_sen,
355	                             'reason', btrim(p_reason)));
356	
357	  return query select 'rejected'::text;
358	end;
359	$$;
