361	-- ---------------------------------------------------------------------------------------------
362	-- void_payment (R24, D14): removes only this payment's allocations; other payments untouched.
363	-- ---------------------------------------------------------------------------------------------
364	create or replace function private.void_payment(p_actor_id uuid, p_payment_id uuid, p_reason text)
365	returns table(status text)
366	language plpgsql
367	security invoker
368	set search_path = ''
369	as $$
370	#variable_conflict use_column
371	declare
372	  v_pay public.payments;
373	  v_released bigint;
374	begin
375	  v_pay := private.lock_payment_for_manager(p_actor_id, p_payment_id);
376	
377	  if p_reason is null or length(btrim(p_reason)) < 5 then
378	    raise exception using errcode = 'P0400', message = 'Reason must be at least 5 characters';
379	  end if;
380	  if v_pay.status <> 'approved' then
381	    raise exception using errcode = 'P0409', message = 'Payment is not approved';
382	  end if;
383	
384	  with d as (
385	    delete from public.payment_allocations a where a.payment_id = p_payment_id returning a.amount_sen
386	  )
387	  select coalesce(sum(d.amount_sen), 0) into v_released from d;
388	
389	  -- D14: unapplied_sen of other payments is NOT re-applied to the reopened invoices.
390	  -- decided_by/decided_at keep the approver; the voider is recorded in audit_log.
391	  update public.payments p
392	     set status = 'voided', reason = btrim(p_reason)
393	   where p.id = p_payment_id;
394	
395	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
396	  values (v_pay.org_id, p_actor_id, 'payment.voided', p_payment_id,
397	          jsonb_build_object('lease_id', v_pay.lease_id, 'amount_sen', v_pay.amount_sen,
398	                             'released_sen', v_released, 'reason', btrim(p_reason)));
399	
400	  return query select 'voided'::text;
401	end;
402	$$;
