404	-- ---------------------------------------------------------------------------------------------
405	-- create_gateway_bill (R30, D5): bill for what is due on or before today's Malaysia date.
406	-- ---------------------------------------------------------------------------------------------
407	create or replace function private.create_gateway_bill(
408	  p_actor_id uuid,
409	  p_lease_id uuid,
410	  p_as_of timestamptz default now()
411	)
412	returns table(id uuid, amount_sen bigint)
413	language plpgsql
414	security invoker
415	set search_path = ''
416	as $$
417	#variable_conflict use_column
418	declare
419	  v_lease record;
420	  v_today date;
421	  v_due bigint;
422	  v_id uuid;
423	begin
424	  -- D7: lease lock so the due amount is computed against committed allocations.
425	  select l.id, l.org_id, l.tenant_id
426	    into v_lease
427	    from public.leases l
428	   where l.id = p_lease_id
429	     for update;
430	  if not found then
431	    raise exception using errcode = 'P0404', message = 'Lease not found';
432	  end if;
433	
434	  -- R1/R37: only the lease's own tenant (tenants.user_id), never another tenant or org.
435	  if not exists (select 1 from public.tenants t
436	                  where t.id = v_lease.tenant_id
437	                    and t.org_id = v_lease.org_id
438	                    and t.user_id = p_actor_id) then
439	    raise exception using errcode = 'P0404', message = 'Lease not found';
440	  end if;
441	
442	  -- D5: "today" is the Malaysia calendar date of p_as_of, never the server's zone.
443	  v_today := (p_as_of at time zone 'Asia/Kuala_Lumpur')::date;
444	
445	  -- R30/D13: unpaid amounts of invoices due on or before today; pending manual payments ignored.
446	  select coalesce(sum(greatest(i.amount_sen - coalesce((select sum(a.amount_sen)
447	                                                          from public.payment_allocations a
448	                                                         where a.invoice_id = i.id), 0), 0)), 0)
449	    into v_due
450	    from public.invoices i
451	   where i.lease_id = p_lease_id
452	     and i.due_date <= v_today;
453	
454	  if v_due <= 0 then
455	    raise exception using errcode = 'P0422', message = 'Nothing is due';
456	  end if;
457	
458	  -- R30: bill id = gen_random_uuid() column default (122 random bits, not guessable).
459	  insert into public.gateway_bills as b (org_id, lease_id, amount_sen, status, created_by)
460	  values (v_lease.org_id, p_lease_id, v_due, 'pending', p_actor_id)
461	  returning b.id into v_id;
462	
463	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
