1	-- T4 smoke test for the private money functions. Runs in one transaction that ROLLS BACK.
2	-- Usage (from ./app): bash ../scripts/with-db.sh psql postgresql://postgres:postgres@127.0.0.1:54322/postgres -v ON_ERROR_STOP=1 -f supabase/tests/money_smoke.sql
3	-- Every expectation that fails raises 'FAIL ...', which stops psql with a non-zero exit.
4	\set ON_ERROR_STOP 1
5	begin;
6	
7	create temp table smoke_ids (k text primary key, v uuid) on commit drop;
8	
9	do $$
10	declare
11	  c_org  uuid := 'a0000000-0000-4000-8000-000000000001';
12	  c_org2 uuid := 'a0000000-0000-4000-8000-000000000002';
13	  c_mgr  uuid := 'b0000000-0000-4000-8000-000000000001';
14	  c_stf  uuid := 'b0000000-0000-4000-8000-000000000002';
15	  c_tusr uuid := 'b0000000-0000-4000-8000-000000000003';
16	  c_mgr2 uuid := 'b0000000-0000-4000-8000-000000000004';
17	  c_unit uuid := 'c0000000-0000-4000-8000-000000000001';
18	  c_ten  uuid := 'd0000000-0000-4000-8000-000000000001';
19	  c_lease uuid := 'e0000000-0000-4000-8000-000000000001';
20	  u uuid;
21	begin
22	  foreach u in array array[c_mgr, c_stf, c_tusr, c_mgr2] loop
23	    insert into auth.users (instance_id, id, aud, role, email, created_at, updated_at)
24	    values ('00000000-0000-0000-0000-000000000000', u, 'authenticated', 'authenticated',
25	            u::text || '@smoke.test', now(), now());
26	  end loop;
27	
28	  insert into public.organizations (id, name) values (c_org, 'Smoke Org'), (c_org2, 'Other Org');
29	  insert into public.memberships (user_id, org_id, role)
30	  values (c_mgr, c_org, 'manager'), (c_stf, c_org, 'staff'), (c_mgr2, c_org2, 'manager');
31	  insert into public.units (id, org_id, name) values (c_unit, c_org, 'S-1');
32	  insert into public.tenants (id, org_id, user_id, full_name, email)
33	  values (c_ten, c_org, c_tusr, 'Smoke Tenant', 'tenant@smoke.test');
34	  insert into public.leases (id, org_id, unit_id, tenant_id, start_date, end_date, monthly_rent_sen, deposit_sen)
35	  values (c_lease, c_org, c_unit, c_ten, '2026-01-31', '2026-07-15', 150000, 300000);
36	  -- Aisyah's schedule (brief R15): deposit + 6 periods, last one prorated to 77419. Total 1127419.
37	  insert into public.invoices (org_id, lease_id, kind, period_index, period_start, period_end, due_date, amount_sen) values
38	    (c_org, c_lease, 'deposit', null, null, null, '2026-01-31', 300000),
39	    (c_org, c_lease, 'rent', 0, '2026-01-31', '2026-02-27', '2026-01-31', 150000),
40	    (c_org, c_lease, 'rent', 1, '2026-02-28', '2026-03-30', '2026-02-28', 150000),
41	    (c_org, c_lease, 'rent', 2, '2026-03-31', '2026-04-29', '2026-03-31', 150000),
42	    (c_org, c_lease, 'rent', 3, '2026-04-30', '2026-05-30', '2026-04-30', 150000),
43	    (c_org, c_lease, 'rent', 4, '2026-05-31', '2026-06-29', '2026-05-31', 150000),
44	    (c_org, c_lease, 'rent', 5, '2026-06-30', '2026-07-15', '2026-06-30', 77419);
45	  insert into storage.objects (bucket_id, name) values
46	    ('payment-slips', c_org::text || '/' || c_lease::text || '/slip1.png'),
47	    ('payment-slips', c_org2::text || '/x/foreign.png');
48	  raise notice 'setup: org, lease (total 1127419 sen, 7 invoices), manager, staff, tenant user, slips';
49	end $$;
50	
51	do $$
52	declare
53	  c_org  uuid := 'a0000000-0000-4000-8000-000000000001';
54	  c_mgr  uuid := 'b0000000-0000-4000-8000-000000000001';
55	  c_stf  uuid := 'b0000000-0000-4000-8000-000000000002';
56	  c_tusr uuid := 'b0000000-0000-4000-8000-000000000003';
57	  c_mgr2 uuid := 'b0000000-0000-4000-8000-000000000004';
58	  c_lease uuid := 'e0000000-0000-4000-8000-000000000001';
59	  c_key  uuid := 'f0000000-0000-4000-8000-000000000001';
60	  v_slip text := 'a0000000-0000-4000-8000-000000000001/e0000000-0000-4000-8000-000000000001/slip1.png';
61	  r record;
62	  v_cash uuid; v_bank uuid; v_idem uuid; v_bill1 uuid; v_bill2 uuid; v_bill3 uuid; v_pay uuid;
63	  v_alloc text; v_n int; v_state text;
64	begin
65	  -- 1. manager cash RM4,000 -> approved, allocated deposit (300000) then period 0 (100000)
66	  select * into r from private.record_payment(c_mgr, c_lease, 400000, 'cash', '2026-01-31T10:00:00+08:00', null, null);
67	  v_cash := r.id;
68	  select string_agg(coalesce(i.kind || coalesce(i.period_index::text, ''), '') || '=' || a.amount_sen, ','
69	                    order by i.due_date, (i.kind = 'rent'), i.period_index nulls first)
70	    into v_alloc
71	    from public.payment_allocations a join public.invoices i on i.id = a.invoice_id
72	   where a.payment_id = v_cash;
73	  if r.status <> 'approved' or r.replayed or v_alloc <> 'deposit=300000,rent0=100000' then
74	    raise exception 'FAIL 1: % % %', r.status, r.replayed, v_alloc;
75	  end if;
76	  raise notice 'ok 1 manager cash 400000 -> % allocations [%]', r.status, v_alloc;
77	
78	  -- 2. staff bank transfer with slip -> pending, nothing allocated
79	  select * into r from private.record_payment(c_stf, c_lease, 200000, 'bank_transfer', '2026-03-01T00:30:00+08:00', v_slip, null);
80	  v_bank := r.id;

